B.NI=new A.cs("Choose your name","intro_choose_player_name",!0,!1)
B.Uk=s([B.NI],t.u)
B.Ov=new A.ch(B.al,B.WV,null,null,null,B.Uk)
B.TR=s([B.Ov],t.J)
B.NX=new A.cM("Concerned Stranger",B.TR)
B.UJ=s(["Welcome, captain. Your ship has good bones, but there is always room for finer work.","Would you like to order work on your ship?"],t.s)
B.NF=new A.cs("View ship upgrades","open_ship_upgrade_menu",!1,!0)
B.WZ=s([B.NF,B.fV],t.u)
